from math import isqrt

def sum_primes_below(n: int) -> int:
    """
    Returns the sum of all prime numbers strictly less than n.
    """
    if n <= 2:
        return 0

    primes = [True] * n
    primes[0] = primes[1] = False

    for i in range(2, isqrt(n) + 1):
        if primes[i]:
            for j in range(i*i, n, i):
                primes[j] = False

    return sum(i for i, prime in enumerate(primes) if prime)

print(sum_primes_below(20))
