def lis_length(nums: List[int]) -> int:
    """
    Returns the length of the longest strictly increasing subsequence.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

